  }                                                                    \
  catch (const std::invalid_argument& e) {                             \
    vkernels::capi::set_last_error(VK_ERROR_INVALID_ARGUMENT, e.what()); \
    return VK_ERROR_INVALID_ARGUMENT;                                  \
